insert into public.knowledge_docs (user_id, title, category, content) values
('da7607ca-e219-4d74-929c-892bc3a01d5d', '价格异议：贵了20%标准应对', 'objection', E'**核心策略**：不接价格战，转向总成本和风险账。\n\n**应对步骤**：\n1. 先认同再转折：「您关注成本说明是行家，单纯比数字我们确实不是最低的」\n2. 拆解贵在哪：把20%差价拆到服务年限/故障率/售后响应上算年化成本\n3. 抛风险账：停产一天损失多少？我们承诺48小时到场 vs 对家72小时\n4. 给台阶：如果预算确实卡死，可以谈配置降级方案，但底线价不动\n\n**禁忌**：一上来就打折；贬低竞品；说「一分钱一分货」这种空话'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '拖延型客户：再说考虑考虑', 'objection', E'**识别**：连续两次说考虑、约下次时间模糊=真拖延或没兴趣\n\n**应对**：\n1. 把考虑具体化：「您主要是在对比哪方面？价格/效果/还是内部流程？」\n2. 设截止钩子：本月签约有X优惠，下月恢复原价（真实存在的政策才用）\n3. 降低决策压力：先推小单试用/试点，别逼大单\n4. 三次拖延直接降级跟进频率，转培育池，时间花给爽快客户\n\n**禁忌**：追问「到底什么时候定」；频繁发消息轰炸'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '「我要问领导/老板」决策人不在场', 'objection', E'**本质判断**：八成是真需要上报，两成是软拒绝。别赌，按真的处理。\n\n**应对**：\n1. 争取同席：「这方案涉及一些细节参数，您汇报时老板可能会问，要不要我一起过去讲？省得信息传递有偏差」\n2. 提供弹药：做一页纸汇报摘要（痛点/方案/投入产出比），让对接人拿着去讲\n3. 埋时间钩子：「您大概什么时候方便汇报？我周四跟进一下进展」——拿到具体时间\n4. 判断真假：如果对接人连摘要都不要，警惕他在中间卡位\n\n**禁忌**：说「那等您消息」就真等；绕过对接人直接联系老板'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '「已经有供应商了」现有供应商壁垒应对', 'objection', E'**客户原话特征**：「我们一直用XX家的」「合作很多年了」「挺稳定的」「暂时不考虑换」
insert into public.knowledge_docs (user_id, title, category, content) values
('da7607ca-e219-4d74-929c-892bc3a01d5d', '首次拜访90秒开场模板', 'script', E'**结构**：身份→来意→价值钩子→开放问题\n\n**话术**：\n「王总您好，我是XX公司的[名字]。今天冒昧来访，是因为我们刚帮[同行业标杆公司]解决了一个[具体问题]，效果是[量化数据]。我注意到贵司最近在[扩产/招聘/新品]，想用15分钟聊聊这个经验对你们有没有参考价值。先请教一下：目前这块业务您最头疼的是什么？」\n\n**要点**：标杆案例必须真实可查；钩子问题一定开放式；全程不超过90秒，把话筒交给客户'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '电话邀约话术与节奏', 'script', E'**黄金时段**：周二到周四，上午10-11点半、下午2-4点。周一早上和周五下午别打。\n\n**开场30秒定生死**：\n「王总您好，我是[公司][名字]。知道您时间宝贵，就占用一分钟：我们刚帮[同行]把[指标]提升了[X%]，我看贵司也在做[相关业务]，想约15分钟给您看下案例细节。您本周三下午还是周四上午方便？」——二选一法收尾，不给拒绝空间\n\n**被拒应对**：\n「理解。那我先把案例发您微信，您有空扫一眼，我下周再跟您约」——退一步留钩子，别硬磨\n\n**纪律**：每天固定时段打20通，记录每通的卡点，周末复盘话术'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '微信跟进节奏与模板', 'script', E'**节奏**：报价后第2天、第5天、第12天三次触点，之后每周一次轻触达\n\n**D+2模板**：报价单发过去后「王总，昨天的资料有空看下，重点在第2页的成本对比表。有任何疑问随时电话我」\n**D+5模板**：分享一个同行业案例链接+一句话点评\n**D+12模板**：「王总，月底我们排产比较满，如果您这边计划定了，提前说一声我给您留产能」\n\n**禁忌**：连发三条60秒语音；只发「在吗」「考虑得怎么样了」；深夜发工作消息'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '报价后的临门一脚话术', 'script', E'**时机判断**：客户开始问细节=进入成交窗口\n\n**三段促单**：\n1. 试探确认：「整体方案您觉得还有哪里需要调整？」——找出最后一个障碍\n2. 假设成交：「那我按今天的沟通版本拟合同，明天上午发您过目？」\n3. 临门收口：客户犹豫时「这样，我给您保留这个报价到本周五，周五前定下来我还额外申请了XX」\n\n**沉默的力量**：说出价格后闭嘴，谁先开口谁被动。客户沉默时你微笑等待即可\n\n**禁忌**：客户一犹豫就主动降价；报完价自己先慌着补充解释');
insert into public.knowledge_docs (user_id, title, category, content) values
('da7607ca-e219-4d74-929c-892bc3a01d5d', '竞品对比FABE框架与原则', 'competitor', E'**铁律**：只做客观参数对比，绝不攻击对手\n\n**框架**：FABE——特征(F)、优势(A)、利益(B)、证据(E)\n客户提竞品时先问：「您看中他们哪一点？」——摸清客户真实需求再针对性打\n差异化打法：把竞品优势转化为「他们适合A场景，我们在B场景更强」，引导客户说出自己的场景\n留口德：万一客户最终选了对手，好话留三分，转介绍和人脉都在后头'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '面对低价竞争者的打法', 'competitor', E'**场景**：对手报价比你低30%，客户拿来压价\n\n**应对**：\n1. 先探虚实：「他们的配置清单方便发我一份吗？我帮您对比下差异」——很多低价是减配换来的\n2. 拆解低价构成：人工外包？材料降级？售后收费？把隐性成本显性化\n3. 算总账：采购价+使用成本+故障损失+更换风险=真实成本\n4. 定位切割：「如果只看采购价选他们是理性的。但如果看三年总成本，我们可以算笔账」\n\n**禁忌**：跟着降价——你永远降不过不要底线的人，还把自己品牌做贱了');
insert into public.knowledge_docs (user_id, title, category, content) values
('da7607ca-e219-4d74-929c-892bc3a01d5d', '老客户转介绍SOP', 'case', E'**时机**：交付满意后1个月内、客户夸你的时候\n\n**话术**：「王总您这么说我太开心了。方便的话，您同行里有没有也受这个问题困扰的朋友？您帮我引荐一下，我肯定像服务您一样服务他，绝不会让您丢面子。」\n**激励**：转介绍成交后送增值服务或返利，说到做到\n**数据参考**：坚持执行的销冠靠转介绍能覆盖40%+新客来源，获客成本趋近于零'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '从丢单复盘认领线索的方法', 'case', E'**丢单不是终点是情报**：每个丢单都要复盘三个问题\n\n1. 输在哪：价格？关系？时机？产品硬伤？——诚实归因\n2. 客户最终选了谁、为什么：半年后回访，多数客户愿意告诉你真相\n3. 这单教会我什么：写进自己的知识库，同类场景不再踩坑\n\n**复购奇迹**：丢单客户保持礼貌触达，行业里供应商翻车时你就是第一个被想起的备胎。真实案例：某销冠30%的单来自两年前丢单的客户');
insert into public.knowledge_docs (user_id, title, category, content) values
('da7607ca-e219-4d74-929c-892bc3a01d5d', '成交信号识别清单', 'other', E'**语言信号**：开始问细节（交付周期/付款方式/售后服务）、主动谈实施、拉同事进对话、问「如果买了之后…」\n**行为信号**：主动要报价明细、约你见上级、给你内部联系人名片\n**应对**：一旦出现两个以上信号，立即收尾促单：「要不这样，我今天回去就把合同草稿拟出来，您明天过目？」——别恋战讲产品，讲多了反而生变'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '客户画像五维评估法（判断该花多少精力）', 'other', E'**五维打分（各20分）**：\n1. 需求度：他的痛是不是我们的药能治的\n2. 预算力：有钱没钱、钱在谁手里\n3. 决策链：对接人能不能拍板、拍板人见不见你\n4. 时间窗：多久内有采购计划\n5. 关系基础：有没有内线、引荐人靠谱程度\n\n**80分+**：全力攻坚，一周两次触达\n**60-80分**：正常节奏跟进\n**40-60分**：低成本培育，月度触达\n**40分以下**：礼貌放弃，别浪费子弹\n\n**核心思想**：销售最大的成本不是时间是被垃圾线索拖死的士气'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '大客户决策链地图绘制法', 'other', E'**角色识别**：使用者（用的人）、把关者（技术/采购）、决策者（签字的）、教练（帮你说话的内线）\n\n**绘制方法**：\n1. 画出组织架构图，标出每个人在本次采购中的角色和态度（支持/中立/反对）\n2. 找到教练：那个愿意告诉你内部信息的人——对TA最好，给足面子和专业支持\n3. 决策者策略：中层搞不定的事，争取一次高层会面，带上标杆案例\n4. 反对者处理：别硬刚，找到TA反对的真实原因（动了谁的蛋糕？），逐个化解或架空\n\n**禁忌**：只跟对接人单线联系——他一旦离职你就出局'),
('da7607ca-e219-4d74-929c-892bc3a01d5d', '销售时间管理四象限', 'other', E'**核心原则**：销售的收入 = 有效客户沟通时长 × 单位转化率。一切不产生客户触达的工作都是伪工作\n\n**四象限**：\n- 重要紧急：今天要报价的单、马上到期的合同 → 立刻干\n- 重要不紧急：客户关系培育、行业知识学习、转介绍经营 → 每天固定2小时\n- 紧急不重要：临时会议、非关键客户的琐碎请求 → 能推就推\n- 不重要不紧急：刷手机、无效社交 → 戒掉\n\n**每日铁律**：拜访/通话前做好情报准备（10分钟）；每晚花15分钟记录当日客户反馈进CRM——三个月后你会感谢这些记录');